// spec: specs/delivery.md §9 · кейс .qa/tests/delivery/dlv-13-order-stage-feminine.md
// seed: tests/seed.admin.spec.ts (+ buyer.json; водитель — «כניסה כעובד» из admin-окна, как driver.spec.ts)
// #7ae889 (עבר QA 25.10; c195176 + fc288c8): этап заказа и всё, что на него ссылается, — в женском роде на всех экранах:
// admin /orders (колонка и фильтр «שלב ההזמנה»), карточка заказа (кнопки «סמן כמוכנה/כיצאה למשלוח», «סמן כסופקה», «סופקה בתאריך»),
// /delivery (группы «מוכנות למשלוח», «סופקו»), карточка клиента «סטטוס משלוח», водитель («יצאה למשלוח», «סימון כסופקה»),
// клиент «ההזמנות שלי». Мужские формы ищутся регэкспом MASC. Только чтение (кроме «כניסה כעובד» — без действий над заказами).
// Названия этапов у клиента могут отличаться от admin («אושרה · בהכנה», «יצאה למשלוח») — норма (решение 20.10).
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

/** Мужские формы этапа/доставки, которых больше быть не должно. «סופקו» (мн. ч.) — допустимо. */
const MASC = /ממתין ל|מוכן למשלוח|כמוכן |יצא למשלוח|כיצא |סופק(?![הו])|טרם סופק(?!ה)/;
const ADMIN_STAGES = ['ממתינה לאישור', 'ממתינה לליקוט', 'בליקוט במחסן', 'מוכנה למשלוח', 'בדרך ללקוח', 'סופקה', 'נדחתה'];
const FEM_ACTIONS = ['סמן כמוכנה למשלוח', 'סמן כיצאה למשלוח', 'סמן כסופקה'];
const CUSTOMER_TEST = '/customers/a30f4767-3f86-4a49-a441-ecfd2faad6d0';
const DRIVER = 'יוסי הנהג';

const rows = (page: Page) => page.getByRole('button', { name: /^#\d+ / });
const mainText = async (page: Page) => (await page.getByRole('main').innerText()).replace(/\s+/g, ' ');
const masc = (s: string) => s.match(new RegExp(`.{0,30}(?:${MASC.source}).{0,10}`))?.[0] ?? null;

async function openOrdersFiltered(page: Page, stage?: string) {
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await expect(rows(page).first()).toBeVisible({ timeout: 30_000 });
  if (!stage) return;
  await page.getByRole('button', { name: 'סינון' }).click();
  await page.getByRole('combobox', { name: 'שלב ההזמנה' }).selectOption({ label: stage });
  await expect(rows(page).first().or(page.getByText('לא נמצאו הזמנות התואמות לסינון'))).toBeVisible({ timeout: 20_000 });
}

test.describe('delivery — שלב ההזמנה בלשון נקבה בכל המסכים (#7ae889)', () => {
  test.describe('מפיץ', () => {
    test.use({ storageState: auth('admin') });

    test('«הזמנות»: אפשרויות הסינון «שלב ההזמנה» ועמודת השלב — בנקבה #7ae889 @desktop @prod-safe', async ({ page }) => {
      await openOrdersFiltered(page);
      await page.getByRole('button', { name: 'סינון' }).click();
      const stageSel = page.getByRole('combobox', { name: 'שלב ההזמנה' });
      const options = (await stageSel.locator('option').allInnerTexts()).map((t) => t.trim());
      for (const s of ADMIN_STAGES) expect(options, `в фильтре есть «${s}»`).toContain(s);
      for (const o of options) expect(o, 'вариант фильтра без мужского рода').not.toMatch(MASC);

      for (const s of ADMIN_STAGES) {
        await stageSel.selectOption({ label: s });
        await expect(rows(page).first().or(page.getByText('לא נמצאו הזמנות התואמות לסינון'))).toBeVisible({ timeout: 20_000 });
        const n = await rows(page).count();
        for (let i = 0; i < n; i++) {
          await expect(rows(page).nth(i)).toHaveAccessibleName(new RegExp(s));
          await expect(rows(page).nth(i)).not.toHaveAccessibleName(MASC);
        }
      }
    });

    test('כרטיס הזמנה בכל שלב: כפתורים והנחיות בנקבה, «סופקה בתאריך» #7ae889 @desktop @prod-safe', async ({ page }) => {
      const checked: string[] = [];
      for (const s of ['ממתינה לליקוט', 'בליקוט במחסן', 'מוכנה למשלוח', 'בדרך ללקוח', 'סופקה']) {
        await openOrdersFiltered(page, s);
        if (!(await rows(page).count())) continue;
        await rows(page).first().click();
        await expect(page.getByRole('heading', { level: 1, name: /^הזמנה #\d+/ })).toBeVisible({ timeout: 30_000 });
        await expect(page.getByRole('heading', { level: 1 }).locator('..')).toContainText(s, { timeout: 20_000 });
        expect(masc(await mainText(page)), `карточка «${s}»: мужская форма`).toBeNull();
        const actions = page.getByRole('button', { name: /^סמן כ/ });
        for (const name of (await actions.allInnerTexts()).map((t) => t.trim())) expect(FEM_ACTIONS, `кнопка «${name}» (этап «${s}»)`).toContain(name);
        if (s === 'ממתינה לליקוט') await expect(page.getByRole('button', { name: 'סמן כמוכנה למשלוח' })).toBeVisible();
        if (s === 'סופקה') await expect(page.getByText(/^סופקה בתאריך/).first()).toBeVisible();
        checked.push(s);
      }
      expect(checked.length, 'хотя бы один этап проверен').toBeGreaterThan(0);
      test.info().annotations.push({ type: 'stages', description: checked.join(', ') });
    });

    test('«משלוחים»: קבוצות «מוכנות למשלוח» / «סופקו», תגים בנקבה #7ae889 @desktop @prod-safe', async ({ page }) => {
      await page.goto('/delivery');
      await expect(page.getByRole('heading', { level: 1, name: 'משלוחים' })).toBeVisible({ timeout: 30_000 });
      await expect(page.getByRole('heading', { level: 2 }).first().or(page.getByText(/אין משלוחים/).first())).toBeVisible({ timeout: 30_000 });
      expect(masc(await mainText(page)), 'доска: мужская форма').toBeNull();
      if (await page.getByRole('link', { name: /^תעודת משלוח · הזמנה #\d+/ }).count()) {
        const groups = (await page.getByRole('heading', { level: 2 }).allInnerTexts()).join(' | ');
        expect(groups, 'группы доски').not.toMatch(/מוכן למשלוח|ממתין להכנה/);
      }
      await page.getByRole('button', { name: 'הצגת משלוחים שסופקו' }).click();
      await expect(page.getByRole('heading', { level: 2, name: /^סופקו/ })).toBeVisible({ timeout: 30_000 });
      expect(masc(await mainText(page)), 'доска + «סופקו»: мужская форма').toBeNull();
    });

    test('כרטיס לקוח «test»: «סטטוס משלוח» וסינון — טרם סופקה / מוכנה למשלוח / במשלוח / סופקה #7ae889 @desktop @prod-safe', async ({ page }) => {
      await page.goto(CUSTOMER_TEST);
      await expect(page.getByRole('heading', { level: 3, name: 'הזמנות אחרונות' })).toBeVisible({ timeout: 30_000 });
      const sel = page.getByRole('combobox', { name: 'סינון לפי סטטוס משלוח' });
      const options = (await sel.locator('option').allInnerTexts()).map((t) => t.trim());
      for (const s of ['טרם סופקה', 'מוכנה למשלוח', 'במשלוח', 'סופקה']) expect(options, `в фильтре «סטטוס משלוח» есть «${s}»`).toContain(s);
      for (const o of options) expect(o).not.toMatch(MASC);
      await expect(page.getByRole('button', { name: /^הזמנה #\d+/ }).first()).toBeVisible({ timeout: 20_000 });
      expect(masc(await mainText(page)), 'карточка клиента: мужская форма').toBeNull();
    });

    test('נהג (כניסה כעובד): «יצאה למשלוח», «סימון כסופקה», טקסט ההסבר בנקבה #7ae889 @desktop', async ({ page }) => {
      await page.goto('/team');
      await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible({ timeout: 30_000 });
      const row = page.locator('div').filter({ hasText: DRIVER }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).last();
      await row.getByRole('button', { name: 'פעולות' }).click();
      await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
      await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
      await expect(page.getByText(`מחובר/ת כרגע בתור ${DRIVER} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 30_000 });
      try {
        await expect(page).toHaveURL(/\/delivery/, { timeout: 20_000 });
        await expect(page.getByText('רשימת החלוקה שלך. לחצו על הזמנה לפתיחת תעודת המשלוח; «יצאה למשלוח» ביציאה מהמחסן, ו«סופקה» לאחר המסירה ללקוח')).toBeVisible({ timeout: 20_000 });
        for (const name of (await page.getByRole('button', { name: /למשלוח$|כסופק/ }).allInnerTexts()).map((t) => t.trim()))
          expect(['יצאה למשלוח', 'סימון כסופקה'], `кнопка водителя «${name}»`).toContain(name);
        expect(masc(await mainText(page)), 'список водителя: мужская форма').toBeNull();
      } finally {
        await page.getByRole('button', { name: 'חזרה לחשבון הניהול' }).click();
        await expect(page.getByText('מפיץ ראשי').first()).toBeVisible({ timeout: 20_000 });
      }
    });
  });

  test.describe('לקוח', () => {
    test.use({ storageState: auth('buyer') });

    test('«ההזמנות שלי» (390): הכל / פתוחות / הושלמו — שלבים בנקבה #7ae889 @iphone @prod-safe', async ({ page }) => {
      await page.setViewportSize({ width: 390, height: 844 });
      await page.goto('/shop/orders');
      await expect(page.getByRole('heading', { level: 1, name: 'ההזמנות שלי' })).toBeVisible({ timeout: 30_000 });
      const tabs = page.getByRole('tablist', { name: 'סינון הזמנות' });
      const list = page.getByRole('link', { name: /^הזמנה #\d+/ });
      const FEM = /ממתינה לאישור|אושרה · בהכנה|יצאה למשלוח|סופקה|נדחתה/;
      for (const t of ['הכל', 'פתוחות', 'הושלמו']) {
        await tabs.getByRole('tab', { name: t }).click();
        await expect(tabs.getByRole('tab', { name: t })).toHaveAttribute('aria-selected', 'true');
        await expect(list.first().or(page.getByText('אין הזמנות בקטגוריה הזו'))).toBeVisible({ timeout: 20_000 });
        const n = await list.count();
        for (let i = 0; i < n; i++) {
          const name = (await list.nth(i).innerText()).replace(/\s+/g, ' ');
          expect(name, `«${t}», строка ${i + 1}: мужская форма`).not.toMatch(MASC);
          expect(name, `«${t}», строка ${i + 1}: этап в женском роде`).toMatch(FEM);
        }
      }
    });
  });
});
